// Aus dem gemeinsamen Job-Pool die passenden Stellen fuer DIESEN Kunden waehlen.
// Reine Rechenarbeit (Textstatistik, keine externe KI), kostet keine Tokens.
var k = $json;

var pool = [];
try { pool = $('Job-Pool bilden').first().json.pool || []; } catch (e) { pool = []; }

if (!pool.length) {
  return [{ json: { no_jobs_found: true } }];
}

var FENSTER_MIN = 10080;
var MAX_BEWERTEN = 6;

var keywords = Array.isArray(k.kunde_keywords) ? k.kunde_keywords : [];
var arten    = Array.isArray(k.kunde_arten) ? k.kunde_arten : [];
// Kunde kann jetzt mehrere Staedte gewaehlt haben ("Leipzig, Berlin").
var staedteListe = String(k.kunde_standort || '').toLowerCase().split(',').map(function (s) { return s.split('(')[0].trim(); }).filter(Boolean);
var remote   = k.kunde_remote === true;

var HAUPT = 14;
var haupt = keywords.slice(0, HAUPT).map(function (w) { return String(w).toLowerCase(); });
var neben = keywords.slice(HAUPT).map(function (w) { return String(w).toLowerCase(); });

function hatWort(text, wort) {
  if (!wort) return false;
  var esc = wort.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  var re = new RegExp('(?:^|[^a-z0-9\u00e4\u00f6\u00fc\u00df])' + esc + '(?:$|[^a-z0-9\u00e4\u00f6\u00fc\u00df])', 'i');
  return re.test(text);
}

var ZU_GENERISCH = ['projektmanagement', 'logistikmanagement', 'sicherheitsüberwachung', 'e-commerce', 'webdesign', 'kundenbetreuung'];

var artMap = {
  werkstudent: ['werkstudent', 'working student'], teilzeit: ['teilzeit'], praktikum: ['praktik'],
  minijob: ['minijob', 'aushilfe', 'nebenjob'], vollzeit: ['vollzeit'],
  abschluss: ['abschlussarbeit', 'bachelorarbeit', 'masterarbeit']
};
var artWoerter = [];
arten.forEach(function (a) { (artMap[a] || []).forEach(function (w) { artWoerter.push(w); }); });

function hatHarteAnforderung(job) {
  var t = (String(job.title || '') + ' ' + String(job.description || '')).toLowerCase();
  var muster = [
    /\babgeschlossenes?\s+(bachelor|master|hochschul|universit[a\u00e4]ts?|fach-?hochschul)\w*\s*(studium|abschluss)/,
    /abgeschlossene\s+ausbildung/,
    /(bachelor|master)abschluss\s+(zwingend|erforderlich|voraussetzung|vorausgesetzt)/,
    /mehrj[a\u00e4]hrige\s+berufserfahrung/,
    /mind(estens)?\.?\s*\d+\s*jahre?\s*(berufs)?erfahrung/,
    /berufserfahrung\s+(zwingend|erforderlich|ist\s+voraussetzung)/,
    /\bsenior\b/, /\blead\b/, /\bhead of\b/, /teamleitung/,
    /nur\s+vollzeit/, /ausschlie[\u00dfs]lich\s+vollzeit/, /100\s*%\s*stelle/
  ];
  return muster.some(function (p) { return p.test(t); });
}

function istRemoteJob(job) {
  var t = (String(job.title || '') + ' ' + String(job.description || '') + ' ' +
           String(job.location || '') + ' ' + String(job.work_model || '')).toLowerCase();
  return /remote|homeoffice|home office|mobiles arbeiten|telearbeit|ortsunabh/.test(t);
}

var IT_STAMM = /software-?entwick|programmier|informatik|frontend|front-end|backend|back-end|full.?stack|data\s*scien|devops|datenbank|datenpflege|datenerfassung|datenanaly|datenmanagement|datenauswertung|it-support|it-sicherheit|cybersecurity|netzwerktechn|systemadmin|cloud engineer|cloud-entwickl|machine learning|data engineer|data analyst|web-?entwickl|anwendungs-?entwickl|qa engineer|testautomat|it-consultant|softwarearchitekt|digitalisierung|business analy|prozessanaly|it-projekt|helpdesk|help desk|1st.level|2nd.level|erste?n?\s*level\s*support|technischer support|it-abteilung|erp-system|sap[\s-]/i;

function fachlichRelevant(job) {
  var text = (String(job.title || '') + ' ' + String(job.description || '')).toLowerCase();
  if (IT_STAMM.test(text)) return true;
  if (hatWort(text, 'ki')) return true;
  var alle = haupt.concat(neben);
  for (var i = 0; i < alle.length; i++) {
    if (!alle[i]) continue;
    if (ZU_GENERISCH.indexOf(alle[i]) !== -1) continue;
    if (alle[i].length <= 4 ? hatWort(text, alle[i]) : text.indexOf(alle[i]) !== -1) { return true; }
  }
  return false;
}

var kandidaten = pool.filter(function (job) {
  if (!job.title) return false;
  if (hatHarteAnforderung(job)) return false;
  var m = job.posted_minutes_ago;
  if (typeof m === 'number' && m > FENSTER_MIN) return false;
  if (!fachlichRelevant(job)) return false;
  if (remote && !istRemoteJob(job)) return false;
  return true;
});

if (!kandidaten.length) {
  return [{ json: { no_jobs_found: true } }];
}

var STOPWORDS = ('der die das und mit fuer bei wir sie ist ein eine du dein deine oder auch sind wird werden haben hat ' +
  'kann koennen nicht als im in am auf zu von an um aus nach ueber unter bis seit waehrend durch ohne gegen wegen ' +
  'statt ausser dich dir dem den des einer einem einen ihr ihre ihrem euch uns unser unsere man was wo wie so ' +
  'schon noch mehr sehr nur immer alle alles jede jeder jedes dieser diese dieses solche diesem diesen').split(' ');
var STOP = {}; STOPWORDS.forEach(function (w) { STOP[w] = true; });

function stem(w) {
  var suffixe = ['ierungen', 'ierung', 'lichkeit', 'ungen', 'heiten', 'keiten', 'ung', 'heit', 'keit',
                 'lich', 'isch', 'bar', 'sam', 'innen', 'erin', 'ern', 'en', 'er', 'es', 'em', 'st', 'e'];
  for (var i = 0; i < suffixe.length; i++) {
    var s = suffixe[i];
    if (w.length - s.length >= 4 && w.slice(-s.length) === s) { return w.slice(0, w.length - s.length); }
  }
  return w;
}

function tokenize(text) {
  return String(text || '').toLowerCase()
    .replace(/[^a-z0-9\u00e4\u00f6\u00fc\u00df\s-]/g, ' ')
    .split(/\s+/)
    .filter(function (w) { return w.length > 2 && !STOP[w]; })
    .map(stem);
}

function buildDF(docs) {
  var df = {};
  docs.forEach(function (tokens) {
    var seen = {};
    tokens.forEach(function (t) { if (!seen[t]) { seen[t] = true; df[t] = (df[t] || 0) + 1; } });
  });
  return df;
}
function tfVector(tokens) {
  var tf = {};
  tokens.forEach(function (t) { tf[t] = (tf[t] || 0) + 1; });
  var total = tokens.length || 1;
  Object.keys(tf).forEach(function (t) { tf[t] = tf[t] / total; });
  return tf;
}
function tfidfVector(tokens, df, N) {
  var tf = tfVector(tokens);
  var vec = {};
  Object.keys(tf).forEach(function (t) {
    var idf = Math.log((N + 1) / ((df[t] || 0) + 1)) + 1;
    vec[t] = tf[t] * idf;
  });
  return vec;
}
function cosine(a, b) {
  var dot = 0, na = 0, nb = 0;
  Object.keys(a).forEach(function (t) { na += a[t] * a[t]; if (b[t]) dot += a[t] * b[t]; });
  Object.keys(b).forEach(function (t) { nb += b[t] * b[t]; });
  if (na === 0 || nb === 0) return 0;
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

var jobDocs = pool.map(function (job) {
  var titleTok = tokenize(job.title);
  var descTok = tokenize((job.description || '').slice(0, 800));
  return titleTok.concat(titleTok).concat(titleTok).concat(descTok);
});
var N = jobDocs.length;
var df = buildDF(jobDocs);
var jobVecs = jobDocs.map(function (toks) { return tfidfVector(toks, df, N); });

var queryTeile = keywords.concat(keywords);
if (k.cv_profil) queryTeile.push(k.cv_profil);
if (k.cv_kenntnisse) queryTeile.push(k.cv_kenntnisse);
if (k.cv_studium) queryTeile.push(k.cv_studium);
var queryTok = tokenize(queryTeile.join(' '));
var queryVec = tfidfVector(queryTok, df, N);

var poolIndex = {};
pool.forEach(function (job, i) { poolIndex[job.url || (job.title + '|' + job.company)] = i; });

kandidaten.forEach(function (job) {
  var idx = poolIndex[job.url || (job.title + '|' + job.company)];
  var sim = (typeof idx === 'number') ? cosine(queryVec, jobVecs[idx]) : 0;

  var bonus = 0;
  var titel = String(job.title || '').toLowerCase();
  var ort = String(job.location || '').toLowerCase();
  for (var j = 0; j < artWoerter.length; j++) { if (titel.indexOf(artWoerter[j]) !== -1) { bonus += 0.01; break; } }
  for (var s = 0; s < staedteListe.length; s++) {
    if (staedteListe[s] && staedteListe[s] !== 'deutschland' && ort.indexOf(staedteListe[s]) !== -1) { bonus += 0.012; break; }
  }
  if (istRemoteJob(job)) { bonus += remote ? 0.012 : 0.006; }
  var m2 = job.posted_minutes_ago;
  if (typeof m2 === 'number') bonus += Math.max(0, 0.005 - (m2 / 1440) * 0.001);

  job.relevanz = Math.round((sim + bonus) * 10000) / 100;
});

kandidaten.sort(function (a, b) {
  if (b.relevanz !== a.relevanz) return b.relevanz - a.relevanz;
  var ma = (typeof a.posted_minutes_ago === 'number') ? a.posted_minutes_ago : 999999;
  var mb = (typeof b.posted_minutes_ago === 'number') ? b.posted_minutes_ago : 999999;
  return ma - mb;
});

var auswahl = kandidaten.slice(0, MAX_BEWERTEN);
return auswahl.map(function (job) {
  var kopie = JSON.parse(JSON.stringify(job));
  kopie.no_jobs_found = false;
  kopie.freshness_window_min = FENSTER_MIN;
  return { json: kopie };
});

// Laeuft pro Stelle einzeln.
function hasHardRequirementKeywords(text) {
  if (!text) return false;
  var t = String(text).toLowerCase();
  var patterns = [
    /abgeschlossenes?\s+(bachelor|master|hochschul|universit[aä]ts?|fach-?hochschul)\w*\s*(studium|abschluss)/,
    /abgeschlossene\s+ausbildung/,
    /(bachelor|master)abschluss\s+(zwingend|erforderlich|voraussetzung|vorausgesetzt)/,
    /mehrj[aä]hrige\s+berufserfahrung/,
    /mind(estens)?\.?\s*\d+\s*jahre?\s*(berufs)?erfahrung/,
    /berufserfahrung\s+(zwingend|erforderlich|ist\s+voraussetzung)/,
    /\bsenior\b/,
    /nur\s+vollzeit/,
    /ausschlie[ßs]lich\s+vollzeit/
  ];
  return patterns.some(function (p) { return p.test(t); });
}

var raw = '';
try { raw = $json.choices[0].message.content; } catch (e) { raw = ''; }

var parsed = {};
try { parsed = JSON.parse(raw); } catch (e) {
  var m = String(raw).match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = {}; } }
}

var job = {};
try { job = $('Bewertung vorbereiten').item.json.job || {}; } catch (e) { job = {}; }

var score = parseInt(parsed.score, 10); if (isNaN(score)) score = 0;

var keywordViolation = hasHardRequirementKeywords(job.description);
var finalViolation = parsed.hard_requirement_violation === true || keywordViolation;

var decision = parsed.decision || 'reject';
if (keywordViolation) {
  decision = 'reject';
  if (score >= 40) score = 39;
}

function alsText(v) {
  if (Array.isArray(v)) return v.join(' \u00b7 ');
  return String(v || '');
}

return { json: Object.assign({}, job, {
  score: score,
  decision: decision,
  reason: parsed.reason || '',
  important_requirements: alsText(parsed.important_requirements),
  missing_requirements: alsText(parsed.missing_requirements),
  hard_requirement_violation: finalViolation,
  keyword_violation_detected: keywordViolation
}) };

function safe(s){ return String(s || '').replace(/[\\/:*?"<>|]/g, '-').slice(0, 80); }
var j = $json;
var folderName = safe(j.company) + ' - ' + safe(j.title);
var today = new Date();
var dd = String(today.getDate()).padStart(2,'0');
var mm = String(today.getMonth()+1).padStart(2,'0');
var yyyy = today.getFullYear();
return { json: Object.assign({}, j, { folder_name: folderName, date_found: today.toISOString().slice(0,10), date_de: dd+'.'+mm+'.'+yyyy }) };

// Angepasstes Kurzprofil und Reihenfolge der Kenntnisse uebernehmen.
// Laeuft pro Stelle einzeln.
var raw = '';
try { raw = $json.choices[0].message.content; } catch (e) { raw = ''; }

var a = {};
try { a = JSON.parse(raw); } catch (e) {
  var m = String(raw).match(/\{[\s\S]*\}/);
  if (m) { try { a = JSON.parse(m[0]); } catch (e2) { a = {}; } }
}

var job = {};
try { job = $('Compute Folder Name').item.json || {}; }
catch (e) {
  try { job = $('Compute Folder Name').first().json || {}; } catch (e2) { job = {}; }
}

var basis = {};
try { basis = $('CV-Daten aufbereiten').first().json.cv || {}; } catch (e) { basis = {}; }

// Kopie anlegen, damit der Ursprung fuer die naechste Stelle unveraendert bleibt.
var cv = JSON.parse(JSON.stringify(basis));

// Sicherheitsfilter: Firmenname und 'passt perfekt'-Floskeln aus dem generierten
// Kurzprofil entfernen, falls das Modell das Verbot im Prompt ignoriert hat.
function bereinigeProfil(text, firma) {
  if (!text) return text;
  var t = String(text);

  if (firma) {
    var namensteile = String(firma).split(/\s+/).filter(function (w) { return w.length > 3; });
    namensteile.forEach(function (teil) {
      var esc = teil.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      var re = new RegExp('\\b' + esc + '\\b', 'gi');
      t = t.replace(re, '');
    });
  }

  var floskeln = [
    /ideal\s+f[uü]r[^.]*?\./gi,
    /passt\s+perfekt\s+zu[^.]*?\./gi,
    /macht\s+ihn\s+ideal[^.]*?\./gi,
    /(,\s*)?was\s+(ihn|sie)\s+ideal[^.,]*?(,|\.)/gi
  ];
  floskeln.forEach(function (re) { t = t.replace(re, ''); });

  // Doppelte Leerzeichen und verwaiste Satzzeichen aufraeumen.
  t = t.replace(/\s{2,}/g, ' ').replace(/\s+([.,])/g, '$1').trim();
  return t;
}

// 1. Kurzprofil auf die Stelle zuschneiden (nur wenn brauchbar).
if (a.profil && String(a.profil).length > 40) {
  cv.profil = bereinigeProfil(String(a.profil).trim(), job.company);
}

// 2. Kenntnisse nach Relevanz sortieren - reine Umsortierung, nichts wird ergaenzt.
if (Array.isArray(a.reihenfolge) && a.reihenfolge.length && Array.isArray(cv.kenntnisse)) {
  var rang = {};
  a.reihenfolge.forEach(function (k, i) { rang[String(k).toLowerCase().trim()] = i; });
  cv.kenntnisse.sort(function (x, y) {
    var rx = rang[String(x.kategorie).toLowerCase().trim()];
    var ry = rang[String(y.kategorie).toLowerCase().trim()];
    if (rx === undefined) rx = 99;
    if (ry === undefined) ry = 99;
    return rx - ry;
  });
}

return { json: Object.assign({}, job, { cv_angepasst: cv }) };

// Laeuft pro Stelle einzeln.
var raw = '';
try { raw = $json.choices[0].message.content; } catch (e) { raw = ''; }

var parsed = {};
try { parsed = JSON.parse(raw); } catch (e) {
  var m = String(raw).match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = {}; } }
}

var job = {};
try { job = $('Parse Anforderungen Match').item.json || {}; }
catch (e) {
  try { job = $('Parse Anforderungen Match').first().json || {}; } catch (e2) { job = {}; }
}

return { json: Object.assign({}, job, {
  firma_name: parsed.firma_name || job.company || '',
  firma_anschrift: parsed.firma_anschrift || '',
  firma_ort: parsed.firma_ort || '',
  betreff: parsed.betreff || ('Bewerbung als ' + (job.title || '')),
  anrede: parsed.anrede || 'Sehr geehrte Damen und Herren,',
  brieftext: parsed.brieftext || ''
}) };

// Alles zusammenfuehren, was das Portal braucht.
var job  = $('Parse Cover Fields').item.json;
var opts = $json;

var cv = job.cv_angepasst;
if (!cv) {
  try { cv = $('CV-Daten aufbereiten').first().json.cv || {}; } catch (e) { cv = {}; }
}

return { json: {
  title:       job.title,
  company:     job.company,
  location:    job.location,
  work_model:  job.work_model,
  url:         job.url,
  score:       job.score,
  reason:      job.reason,
  date_found:  job.date_found,

  has_email:         !!opts.has_email,
  application_email: opts.application_email || '',
  is_portal:         !!opts.is_portal,

  firma_name:      job.firma_name || job.company,
  firma_anschrift: job.firma_anschrift || '',
  firma_ort:       job.firma_ort || '',
  betreff:         job.betreff || ('Bewerbung als ' + job.title),
  anrede:          job.anrede || 'Sehr geehrte Damen und Herren,',
  brieftext:       job.brieftext || '',

  cv_daten: cv
} };

var job = $('Parse Cover Fields').item.json;
function extractEmail(t) {
  if (!t) return '';
  var s = String(t);
  var m = s.match(/[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/);
  if (m) return m[0].toLowerCase();
  var m2 = s.match(/([\w.+-]+)\s*[\(\[]?\s*at\s*[\)\]]?\s*([\w-]+)\s*[\(\[]?\s*dot\s*[\)\]]?\s*([a-zA-Z]{2,})/i);
  if (m2) return (m2[1] + '@' + m2[2] + '.' + m2[3]).toLowerCase();
  return '';
}
var email = extractEmail(job.description);
return { json: { has_email: !!email, application_email: email } };

var job  = $('Parse Cover Fields').item.json;
var prev = $json;

function isPortalUrl(url) {
  if (!url) return false;
  return /myworkday\.com|personio\.(de|com)|greenhouse\.io|lever\.co|successfactors|smartrecruiters|workable\.com/i.test(url);
}

return { json: {
  has_email:         !!prev.has_email,
  application_email: prev.application_email || '',
  is_portal:         isPortalUrl(job.url)
} };

function extractEmail(t) {
  if (!t) return '';
  var s = String(t);
  var m = s.match(/[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/);
  if (m) return m[0].toLowerCase();
  var m2 = s.match(/([\w.+-]+)\s*[\(\[]?\s*at\s*[\)\]]?\s*([\w-]+)\s*[\(\[]?\s*dot\s*[\)\]]?\s*([a-zA-Z]{2,})/i);
  if (m2) return (m2[1] + '@' + m2[2] + '.' + m2[3]).toLowerCase();
  return '';
}
var body = $json.data !== undefined ? $json.data : ($json.body !== undefined ? $json.body : $json);
var text = typeof body === 'string' ? body : JSON.stringify(body);
var email = extractEmail(text);
if (email && /noreply|no-reply|example\.com|sentry\.io|googletagmanager|google-analytics/.test(email)) email = '';
return { json: { has_email: !!email, application_email: email } };

// Strukturierte Lebenslaufdaten lesen und Kundendaten mitreichen.
var raw = '';
try { raw = $json.choices[0].message.content; } catch (e) { raw = ''; }

var d = {};
try { d = JSON.parse(raw); } catch (e) {
  var m = String(raw).match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = {}; } }
}

var kunde = {};
try { kunde = $('Kunde fuer Kunde').first().json || {}; } catch (e) { kunde = {}; }
var api = kunde.api || {};

function liste(v) { return Array.isArray(v) ? v : []; }

var raus = /grundschule|mittelschule|gymnasium|realschule|primary school|secondary school|zertifikat\s*(a1|a2|b1|b2|c1|c2)|^(a1|a2|b1|b2|c1|c2)\b/i;
var bildung = liste(d.bildung).filter(function (b) {
  return b && b.abschluss && !raus.test(String(b.abschluss));
});

var quelltext = '';
try { quelltext = String($('Extract Master CV').first().json.text || ''); } catch (e) { quelltext = ''; }
var geburtsdatum = d.geburtsdatum || '';
if (geburtsdatum && !/geburtsdatum|geboren\s+am|\bgeb\./i.test(quelltext)) {
  geburtsdatum = '';
}

var cv = {
  name:         d.name || kunde.name || '',
  titel:        d.titel || '',
  geburtsdatum: geburtsdatum,
  adresse:      d.adresse || '',
  kontakt:      d.kontakt || kunde.email || '',
  ort:          d.ort || '',
  profil:       d.profil || '',
  erfahrung:    liste(d.erfahrung),
  projekte:     liste(d.projekte),
  bildung:      bildung,
  kenntnisse:   liste(d.kenntnisse),
  sprachen:     liste(d.sprachen)
};

// ---- Ort fuer die Jobboersen aufbereiten ----
// Wichtig: Im Portal steht der ANZEIGETEXT des Auswahlfelds, z.B.
// "Remote / ortsunabhaengig". So etwas als Stadt an Adzuna zu schicken
// ergibt null Treffer. Hier wird daraus ein echter Suchort.
var rohOrt   = String(kunde.standort || '').trim();
var istRemote = kunde.ist_remote === true || /remote|ortsunabh|anywhere|deutschlandweit/i.test(rohOrt);

var suchOrt;
if (istRemote || !rohOrt || /^deutschland$/i.test(rohOrt)) {
  suchOrt = 'Deutschland';
} else {
  // Zusaetze wie "/ anywhere" abschneiden, Klammern wie "(Saale)" behalten.
  suchOrt = rohOrt.split('/')[0].trim();
}

if (!cv.ort) { cv.ort = ( 'Deutschland' === suchOrt ) ? '' : suchOrt; }

// ---- Suchbegriffe zusammenfuehren ----
var ausKatalog = Array.isArray(kunde.keywords) ? kunde.keywords : [];
var ausCV      = liste(d.suchbegriffe).filter(function (w) {
  var s = String(w || '').trim();
  return s.length > 3 && !/^(docker|git|junit|sql|h2|linux|grafana|jira|excel)$/i.test(s);
}).map(function (w) { return String(w).trim(); });

var gesehen = {};
var suchbegriffe = [];
ausKatalog.concat(ausCV).forEach(function (w) {
  var k = String(w).toLowerCase();
  if (k && !gesehen[k]) { gesehen[k] = true; suchbegriffe.push(w); }
});

var kenntnisseText = cv.kenntnisse.map(function (k) {
