// Referenznummern aus der BA-Suchantwort holen.
// Bewusst NICHT nach Teilzeit vorfiltern: die Felder sind nicht zuverlaessig
// gesetzt, und die KI-Bewertung sortiert unpassende Stellen ohnehin aus.
var MAX_DETAILS = 15;
var items = $input.all();
var out = [];
var seen = {};

for (var idx = 0; idx < items.length; idx++) {
  var data = items[idx].json || {};
  if (data.error) continue;

  var list = data.stellenangebote || data.ergebnisliste || [];
  if (!Array.isArray(list)) continue;

  var wo = '';
  try { wo = String($('Build Search Queries').all()[idx].json.where || ''); } catch (e) { wo = ''; }
  var priority = /halle|leipzig|merseburg/i.test(wo) ? 1 : 2;

  for (var i = 0; i < list.length; i++) {
    if (out.length >= MAX_DETAILS) break;
    var j = list[i];
    var refnr = j.refnr || j.referenznummer || '';
    if (!refnr || seen[refnr]) continue;
    seen[refnr] = true;

    var ort = '';
    if (j.arbeitsort) {
      ort = [j.arbeitsort.ort, j.arbeitsort.region].filter(Boolean).join(', ');
    } else if (j.stellenlokationen && j.stellenlokationen[0] && j.stellenlokationen[0].adresse) {
      var ad = j.stellenlokationen[0].adresse;
      ort = [ad.ort, ad.region].filter(Boolean).join(', ');
    }

    out.push({ json: {
      refnr: refnr,
      refnr_b64: Buffer.from(String(refnr)).toString('base64'),
      ba_title: j.titel || j.stellenangebotsTitel || j.beruf || '',
      ba_company: j.arbeitgeber || j.firma || 'Unbekannt',
      ba_location: ort,
      ba_published: j.aktuelleVeroeffentlichungsdatum || j.eintrittsdatum ||
                    j.aenderungsdatum || j.modifikationsTimestamp || '',
      ba_homeoffice: j.homeofficemoeglich === true,
      ba_minijob: j.istGeringfuegigeBeschaeftigung === true,
      priority: priority
    }});
  }
}
return out;

// Wandelt die BA-Detailantwort ins gemeinsame Format um.
var items = $input.all();
var meta = $('Extract BA Refnrs').all();
var out = [];

for (var i = 0; i < items.length; i++) {
  var d = items[i].json || {};
  var m = (meta[i] && meta[i].json) || {};

  var title = d.stellenangebotsTitel || d.titel || m.ba_title || '';
  if (!title) continue;

  var company = d.arbeitgeber || d.firma || m.ba_company || 'Unbekannt';

  var location = m.ba_location || '';
  if (!location && d.arbeitsorte && d.arbeitsorte[0]) {
    var a = d.arbeitsorte[0];
    location = [a.ort, a.region].filter(Boolean).join(', ');
  }
  if (!location) location = 'Deutschland';

  var description = d.stellenangebotsBeschreibung || d.stellenbeschreibung || '';

  var rawDate = d.aenderungsdatum || d.aktuelleVeroeffentlichungsdatum ||
                d.ersteVeroeffentlichungsdatum || m.ba_published || '';
  var minutesAgo = null;
  if (rawDate) {
    var t = new Date(rawDate).getTime();
    if (!isNaN(t)) minutesAgo = Math.round((Date.now() - t) / 60000);
  }

  var parts = [];
  if (m.ba_minijob) parts.push('Minijob'); else parts.push('Teilzeit');
  if (m.ba_homeoffice) parts.push('Homeoffice moeglich');

  out.push({ json: {
    title: title,
    company: company,
    location: location,
    work_model: parts.join(' / '),
    salary: '',
    description: description,
    url: 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent(m.refnr || ''),
    source: 'Bundesagentur fuer Arbeit',
    priority: m.priority || 2,
    posted_at_raw: rawDate,
    posted_minutes_ago: minutesAgo
  }});
}
return out;

// Laeuft pro Stelle einzeln.
