// Gemeinsame Suche: einmal fuer alle Kunden, nicht pro Kunde.
// Aus den Betriebsdaten des Portals entsteht eine Liste von Abfragen.
var antwort = $json;
var sys = antwort.system || {};
var staedte = Array.isArray(sys.staedte) && sys.staedte.length
  ? sys.staedte
  : [{ stadt: 'Leipzig', umkreis: 50 }, { stadt: 'Berlin', umkreis: 30 }];

// ====== EINSTELLUNG ======
// Seiten je Stadt. Adzuna liefert 50 Treffer pro Seite.
// Bei 2 Staedten und 2 Seiten sind das 4 Abfragen pro Durchlauf,
// bei 4 Laeufen taeglich rund 480 im Monat - das Limit liegt bei 1000.
var SEITEN_JE_STADT = 2;
// =========================

// Keine Fachrichtung im Filter: wir sammeln alles, was fuer Studierende
// in Frage kommt. Die Zuordnung zum passenden Kunden passiert spaeter.
var stellenarten = 'Werkstudent Werkstudentin Praktikum Praktikant Teilzeit Minijob Aushilfe Nebenjob Studentenjob Werkstudierende';

var abfragen = [];
for (var i = 0; i < staedte.length; i++) {
  for (var seite = 1; seite <= SEITEN_JE_STADT; seite++) {
    abfragen.push({ json: {
      stadt:      staedte[i].stadt,
      umkreis:    String(staedte[i].umkreis || 30),
      seite:      seite,
      what_or:    stellenarten,
