    var minutesAgo = (postedMs && !isNaN(postedMs)) ? Math.round((Date.now() - postedMs) / 60000) : null;

    out.push({ json: {
      title: r.title || '',
      company: (r.company && r.company.display_name) || '',
      location: (r.location && r.location.display_name) || stadt,
      such_stadt: stadt,
      work_model: r.contract_time === 'part_time' ? 'Teilzeit' : (r.contract_time === 'full_time' ? 'Vollzeit' : 'Unbekannt'),
      salary: '',
      description: r.description || '',
      url: (r.redirect_url || '').trim(),
      source: 'Adzuna',
