// Die Arbeitsagentur verknuepft Suchbegriffe mit UND, deshalb je Stadt
// mehrere schmale Abfragen statt einer breiten.
// Kein Limit bei dieser Quelle - hier darf grosszuegig gesucht werden.
var begriffe = ['Werkstudent', 'Praktikum', 'Teilzeit', 'Minijob'];

var staedte = [];
try {
  var sys = $('Kunden aus WordPress holen').first().json.system || {};
  staedte = Array.isArray(sys.staedte) && sys.staedte.length ? sys.staedte : [];
