if (!staedte.length) {
  staedte = [{ stadt: 'Leipzig', umkreis: 50 }, { stadt: 'Berlin', umkreis: 30 }];
}

var out = [];
for (var i = 0; i < staedte.length; i++) {
  for (var b = 0; b < begriffe.length; b++) {
    out.push({ json: {
      stadt:      staedte[i].stadt,
      umkreis:    String(staedte[i].umkreis || 30),
      ba_begriff: begriffe[b]
    }});
  }
}
return out;

// Beide Quellen zusammenfuehren und entdoppeln.
// Ergebnis ist EIN Pool, der anschliessend auf alle Kunden verteilt wird.
var adzuna = [];
var ba = [];
try { adzuna = $('Adzuna aufbereiten').all().map(function (i) { return i.json; }); } catch (e) { adzuna = []; }
try { ba = $('Normalize Arbeitsagentur').all().map(function (i) { return i.json; }); } catch (e) { ba = []; }

function sauber(u) {
  if (!u) return '';
  return String(u).split('?')[0].split('#')[0].trim().toLowerCase();
}
function text(t) {
  return String(t || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

var gesehenUrl = {};
var gesehenKey = {};
var pool = [];

// Arbeitsagentur zuerst: sie liefert vollstaendige Beschreibungen und
// ist damit fuer Bewertung und Anschreiben die bessere Quelle.
ba.concat(adzuna).forEach(function (job) {
  if (!job || !job.title) return;
  var url = sauber(job.url);
  var key = text(job.title) + '___' + text(job.company);
  if (!url || gesehenUrl[url] || gesehenKey[key]) return;
  gesehenUrl[url] = true;
  gesehenKey[key] = true;
  pool.push(job);
});

// Der Pool haengt an EINEM Element, damit die Kundenschleife ihn
// vollstaendig lesen kann, statt ihn in Einzelteile zu zerlegen.
return [{ json: { pool: pool, anzahl: pool.length, adzuna: adzuna.length, ba: ba.length } }];

// Der Job-Pool steht. Jetzt die Kundenliste wieder hervorholen,
// damit die Schleife pro Kunde laufen kann.
var kunden = [];
try { kunden = $('Kunden aus WordPress holen').first().json.kunden || []; } catch (e) { kunden = []; }

var bereit = kunden.filter(function (k) { return k && k.bereit === true; });

return bereit.map(function (k) { return { json: k }; });
